'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var ln = require( '@stdlib/math/base/special/ln' );
var erf = require( '@stdlib/math/base/special/erf' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a half-normal distribution with scale parameter `sigma` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} evaluated natural logarithm of CDF
*
* @example
* var y = logcdf( 2.0, 1.0 );
* // returns -0.046567912292390164
*
* @example
* var y = logcdf( -1.0, 2.0 );
* // returns -Infinity
*
* @example
* var y = logcdf( 0.0, 1.0 );
* // returns -Infinity
*
* @example
* var y = logcdf( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = logcdf( 0.0, NaN );
* // returns NaN
*
* @example
* // Negative scale parameter:
* var y = logcdf( 2.0, -1.0 );
* // returns NaN
*/
function logcdf( x, sigma ) {
	var denom;
	if (
		isnan( x ) ||
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return NaN;
	}
	if ( x < 0.0 ) {
		return NINF;
	}
	if ( sigma === 0.0 ) {
		return ( x >= 0.0 ) ? 0.0 : NINF;
	}
	denom = sigma * sqrt( 2.0 );
	return ln( erf( x / denom ) );
}


// EXPORTS //

module.exports = logcdf;
